test:
listings = {'Z': [9, 3, 1, 2, 2], 'A': [5, 4, 3, 4, 0]}
before = {name: days[:] for name, days in listings.items()}
assert find_split_pairs(listings, 1, 5) == [('A', 'Z')]
assert listings == before

listings = {'A': (2, 1), 'B': {3, 4}, 'C': range(0)}
assert find_split_pairs(listings, 1, 4) == [('A', 'B')]
assert listings == {'A': (2, 1), 'B': {3, 4}, 'C': range(0)}
